package org.apache.commons.math3.fraction;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class AgentBRT_Math_27_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Create a fraction 2/3
        Fraction fraction = new Fraction(2, 3);
        // Calculate the percentage value
        double percentage = fraction.percentageValue();
        // The expected percentage value should be approximately 66.6667
        assertEquals("The percentage value should be approximately 66.6667", 66.66666666666667, percentage, 1e-10);
